/**
 * Token usage extraction from claude --output-format stream-json stdout.
 */

const PRICING: Record<string, { inputPerMTok: number; outputPerMTok: number }> = {
  "claude-sonnet-4-6": { inputPerMTok: 3.0, outputPerMTok: 15.0 },
  "claude-opus-4-7": { inputPerMTok: 15.0, outputPerMTok: 75.0 },
  "claude-haiku-4-5-20251001": { inputPerMTok: 0.8, outputPerMTok: 4.0 },
};

const FALLBACK_MODEL = "claude-sonnet-4-6";

/**
 * Scan stdout lines for token usage across all formats.
 * Returns accumulated {input, output, model, cost_usd, pricingFallback}, or undefined.
 */
export function extractTokenUsage(
  stdout: string,
): { input: number; output: number; model: string; cost_usd: number; pricingFallback: boolean } | undefined {
  let input = 0;
  let output = 0;
  let lastModel: string | undefined;
  let found = false;

  for (const line of stdout.split("\n")) {
    const trimmed = line.trim();
    if (!trimmed.startsWith("{")) continue;
    try {
      const parsed = JSON.parse(trimmed) as Record<string, unknown>;

      if (parsed.type === "assistant") {
        const msg = parsed.message as Record<string, unknown> | undefined;
        const usage = msg?.usage as Record<string, unknown> | undefined;
        if (
          typeof usage?.input_tokens === "number" &&
          typeof usage?.output_tokens === "number"
        ) {
          input += usage.input_tokens as number;
          output += usage.output_tokens as number;
          found = true;
        }
        if (typeof msg?.model === "string" && msg.model.length > 0) {
          lastModel = msg.model as string;
        }
        continue;
      }

      const usage = parsed.usage as Record<string, unknown> | undefined;
      if (
        typeof usage?.input_tokens === "number" &&
        typeof usage?.output_tokens === "number"
      ) {
        input += usage.input_tokens as number;
        output += usage.output_tokens as number;
        found = true;
      }
    } catch {
      // Not a JSON line — skip.
    }
  }

  if (!found) return undefined;

  const model = lastModel ?? FALLBACK_MODEL;
  const pricingFallback = !Object.prototype.hasOwnProperty.call(PRICING, model);
  const rates = PRICING[model] ?? PRICING[FALLBACK_MODEL]!;
  const cost_usd =
    (input / 1_000_000) * rates.inputPerMTok +
    (output / 1_000_000) * rates.outputPerMTok;

  return { input, output, model, cost_usd, pricingFallback };
}

