1	/**
2	 * Claude executor entrypoint — ABI-conformant.
3	 *
4	 * Reads ExecutorInput from environment variables, materializes the
5	 * implementation repo, spawns `claude -p`, and writes ExecutorResult
6	 * to result.json at RESULT_PATH.
7	 *
8	 * Formal ABI env vars (from ExecutorInput):
9	 *   TASK_ID, FEATURE_ID, WORKSPACE_ID
10	 *   TASK_REPO_URL, TASK_REPO_BRANCH, TASK_REPO_PATH
11	 *   BRIEFING_PATH, RESULT_PATH
12	 *   BUDGET_TOKENS (optional)
13	 *   SSH_PRIVATE_KEY, GITHUB_TOKEN
14	 *
15	 * Day-1 single-container extras (not in formal ABI — passed by SubProcessAdapter):
16	 *   WORKSPACE_ROOT     — management repo root for task YAML reading
17	 *   TASK_BRANCH        — management repo feature branch for git commits
18	 *   GIT_AUTHOR_EMAIL   — for commit identity
19	 *   GIT_AUTHOR_NAME    — for commit identity
20	 *   WORKFLOW_LOCAL_PATH — workflow repo root for skills setup
21	 *   MAX_TURNS          — max claude CLI turns (default: 200)
22	 *   LOG_SINK_ENABLED   — "1" to flush JSONL log to management repo
23	 *   MCP_RAG_URL        — optional RAG server URL for MCP registration
24	 *   FIGMA_PERSONAL_ACCESS_TOKEN — optional Figma MCP
25	 *   CLAUDE_AGENT_RUNTIME — injected as "1" for agent detection
26	 */
27	
28	import { spawn, execSync } from "node:child_process";
29	import {
30	  mkdirSync,
31	  appendFileSync,
32	  readFileSync,
33	  writeFileSync,
34	  existsSync,
35	  readdirSync,
36	  rmSync,
37	  copyFileSync,
38	  lstatSync,
39	} from "node:fs";
40	import { join, dirname } from "node:path";
41	import { homedir } from "node:os";
42	import { parse as parseYaml, stringify as yamlStringify } from "yaml";
43	import type { ExecutorResult } from "@workflow/runtime-abi";
44	import { isValidResult } from "@workflow/runtime-abi";
45	import { extractTokenUsage } from "./token-usage.js";
46	import { extractRagQueries } from "./rag-audit.js";
47	import { enforceInReviewRequiresPrUrl } from "./enforce-pr-url.js";
48	import { runRecovery, type SpawnResult } from "./recovery.js";
49	import { resolveSSHKey } from "./resolve-ssh-key.js";
50	import { redactSecrets } from "./redact-secrets.js";
51	import { buildGitEnv } from "./git-env.js";
52	
53	// ── Helpers ───────────────────────────────────────────────────────────────────
54	
55	function requireEnv(name: string): string {
56	  const val = process.env[name];
57	  if (!val) throw new Error(`Required env var ${name} is not set`);
58	  return val;
59	}
60	
61	function emit(event: Record<string, unknown>): void {
62	  console.log(JSON.stringify({ at: new Date().toISOString(), ...event }));
63	}
64	
65	/**
66	 * Materialize the implementation repo at taskRepoPath:
67	 *   - If path exists and origin matches URL: fetch + checkout + pull
68	 *   - Otherwise: clone fresh
69	 */
70	function materializeRepo(
71	  taskRepoUrl: string,
72	  taskRepoBranch: string,
73	  taskRepoPath: string,
74	  sshKeyPath: string | undefined,
75	): void {
76	  const env = buildGitEnv(sshKeyPath);
77	  const opts = { env, stdio: "pipe" as const };
78	
79	  if (existsSync(join(taskRepoPath, ".git"))) {
80	    let originUrl = "";
81	    try {
82	      originUrl = execSync(`git -C "${taskRepoPath}" remote get-url origin`, {
83	        ...opts, encoding: "utf-8",
84	      }).trim();
85	    } catch { /* no remote — fall through to clone */ }
86	
87	    if (originUrl === taskRepoUrl) {
88	      execSync(`git -C "${taskRepoPath}" fetch origin`, opts);
89	      // Discard local changes from a previous session before checkout.
90	      try { execSync(`git -C "${taskRepoPath}" checkout -- .`, opts); } catch { /* ignore */ }
91	      try {
92	        execSync(`git -C "${taskRepoPath}" checkout "${taskRepoBranch}"`, opts);
93	      } catch {
94	        execSync(`git -C "${taskRepoPath}" checkout -b "${taskRepoBranch}"`, opts);
95	      }
96	      try {
97	        execSync(
98	          `git -C "${taskRepoPath}" pull --ff-only origin "${taskRepoBranch}"`,
99	          opts,
100	        );
101	      } catch {
102	        emit({ type: "repo_pull_diverged", task_repo: taskRepoPath, branch: taskRepoBranch, note: "ff-only failed — working on checked-out ref without latest origin commits" });
103	      }
104	      return;
105	    }
106	  }
107	
108	  // Clone fresh.
109	  mkdirSync(dirname(taskRepoPath), { recursive: true });
110	  if (existsSync(taskRepoPath)) {
111	    rmSync(taskRepoPath, { recursive: true, force: true });
112	  }
113	  execSync(`git clone "${taskRepoUrl}" "${taskRepoPath}"`, opts);
114	  try {
115	    execSync(`git -C "${taskRepoPath}" checkout "${taskRepoBranch}"`, opts);
116	  } catch {
117	    execSync(`git -C "${taskRepoPath}" checkout -b "${taskRepoBranch}"`, opts);
118	  }
119	}
120	
121	const TOOLCHAIN_MARKERS: Array<{ file: string; tool: string }> = [
122	  { file: "yarn.lock",        tool: "yarn"    },
123	  { file: "pnpm-lock.yaml",   tool: "pnpm"    },
124	  { file: "bun.lockb",        tool: "bun"     },
125	  { file: "go.mod",           tool: "go"      },
126	  { file: "requirements.txt", tool: "python3" },
127	  { file: "pyproject.toml",   tool: "python3" },
128	  { file: "Cargo.toml",       tool: "cargo"   },
129	];
130	
131	function checkRequiredTools(taskRepoPath: string): string[] {
132	  const missing: string[] = [];
133	  const checked = new Set<string>();
134	  for (const { file, tool } of TOOLCHAIN_MARKERS) {
135	    if (checked.has(tool)) continue;
136	    if (!existsSync(join(taskRepoPath, file))) continue;
137	    checked.add(tool);
138	    try {
139	      execSync(`which ${tool}`, { stdio: "pipe" });
140	    } catch {
141	      missing.push(tool);
142	    }
143	  }
144	  return missing;
145	}
146	
147	function copyWorkspaceClaude(workspaceRoot: string): void {
148	  const src = join(workspaceRoot, "CLAUDE.md");
149	  if (!existsSync(src)) return;
150	  const destDir = join(homedir(), ".claude");
151	  mkdirSync(destDir, { recursive: true });
152	  copyFileSync(src, join(destDir, "CLAUDE.md"));
153	}
154	
155	function copyDirRecursive(src: string, dest: string): void {
156	  mkdirSync(dest, { recursive: true });
157	  for (const entry of readdirSync(src)) {
158	    const srcPath = join(src, entry);
159	    const destPath = join(dest, entry);
160	    const stat = lstatSync(srcPath);
161	    if (stat.isDirectory()) {
162	      copyDirRecursive(srcPath, destPath);
163	    } else if (stat.isFile()) {
164	      copyFileSync(srcPath, destPath);
165	    }
166	  }
167	}
168	
169	function setupGlobalSkills(workspaceRoot: string, workflowLocalPath: string): void {
170	  const globalSkillsDir = join(homedir(), ".claude", "skills");
171	  if (existsSync(globalSkillsDir)) {
172	    rmSync(globalSkillsDir, { recursive: true, force: true });
173	  }
174	  mkdirSync(globalSkillsDir, { recursive: true });
175	
176	  const copySkillsFrom = (sourceDir: string): void => {
177	    if (!existsSync(sourceDir)) return;
178	    let entries: string[];
179	    try { entries = readdirSync(sourceDir); } catch { return; }
180	    for (const entry of entries) {
181	      const srcPath = join(sourceDir, entry);
182	      try {
183	        const stat = lstatSync(srcPath);
184	        if (!stat.isDirectory()) continue;
185	        copyDirRecursive(srcPath, join(globalSkillsDir, entry));
186	      } catch (e) {
187	        emit({ type: "skill_copy_warn", skill: entry, details: String(e) });
188	      }
189	    }
190	  };
191	
192	  copySkillsFrom(join(workflowLocalPath, "technical_skills"));
193	  copySkillsFrom(join(workflowLocalPath, "workflow_skills"));
194	
195	  const wsSkillsDir = join(workspaceRoot, ".claude", "skills");
196	  if (existsSync(wsSkillsDir)) {
197	    let entries: string[];
198	    try { entries = readdirSync(wsSkillsDir); } catch { entries = []; }
199	    for (const entry of entries) {
200	      if (entry === ".gitignore") continue;
201	      const srcPath = join(wsSkillsDir, entry);
202	      try {
203	        const stat = lstatSync(srcPath);
204	        if (stat.isSymbolicLink() || !stat.isDirectory()) continue;
205	        copyDirRecursive(srcPath, join(globalSkillsDir, entry));
206	      } catch (e) {
207	        emit({ type: "skill_copy_warn", skill: entry, details: String(e) });
208	      }
209	    }
210	  }
211	}
212	
213	function writeResult(resultPath: string, result: ExecutorResult): void {
214	  mkdirSync(dirname(resultPath), { recursive: true });
215	  writeFileSync(resultPath, JSON.stringify(result), "utf-8");
216	}
217	
218	// ── Main ──────────────────────────────────────────────────────────────────────
219	
220	async function main(): Promise<void> {
221	  // ── Read formal ABI env vars ────────────────────────────────────────────────
222	  let taskId: string;
223	  let featureId: string;
224	  let taskRepoUrl: string;
225	  let taskRepoBranch: string;
226	  let taskRepoPath: string;
227	  let briefingPath: string;
228	  let resultPath: string;
229	  let sshKeyPath: string | undefined;
230	  let githubToken: string;
231	
232	  try {
233	    taskId = requireEnv("TASK_ID");
234	    featureId = requireEnv("FEATURE_ID");
235	    taskRepoUrl = requireEnv("TASK_REPO_URL");
236	    taskRepoBranch = requireEnv("TASK_REPO_BRANCH");
237	    taskRepoPath = requireEnv("TASK_REPO_PATH");
238	    briefingPath = requireEnv("BRIEFING_PATH");
239	    resultPath = requireEnv("RESULT_PATH");
240	    githubToken = process.env.GITHUB_TOKEN ?? "";
241	    sshKeyPath = resolveSSHKey({ SSH_PRIVATE_KEY: process.env.SSH_PRIVATE_KEY }).sshKeyPath;
242	  } catch (e) {
243	    emit({ type: "executor_fatal", details: (e as Error).message });
244	    process.exit(1);
245	  }
246	
247	  const budgetTokensStr = process.env.BUDGET_TOKENS;
248	  const budgetTokens = budgetTokensStr ? parseInt(budgetTokensStr, 10) : undefined;
249	
250	  // Day-1 single-container extras.
251	  const workspaceRoot = process.env.WORKSPACE_ROOT ?? "";
252	  const taskBranch = process.env.TASK_BRANCH ?? `feature/${featureId}-${taskId}`;
253	  const gitAuthorEmail = process.env.GIT_AUTHOR_EMAIL ?? "agent@unknown";
254	  const gitAuthorName = process.env.GIT_AUTHOR_NAME ?? gitAuthorEmail;
255	  const workflowLocalPath = process.env.WORKFLOW_LOCAL_PATH ?? "";
256	  const maxTurns = parseInt(process.env.MAX_TURNS ?? "200", 10);
257	  const logSinkEnabled = process.env.LOG_SINK_ENABLED === "1";
258	  const mcpRagUrl = process.env.MCP_RAG_URL;
259	  const figmaToken = process.env.FIGMA_PERSONAL_ACCESS_TOKEN;
260	  const implementationModel = process.env.IMPLEMENTATION_MODEL;
261	
262	  const runStartIso = new Date().toISOString();
263	
264	  // ── 1. Materialize implementation repo ─────────────────────────────────────
265	  try {
266	    materializeRepo(taskRepoUrl, taskRepoBranch, taskRepoPath, sshKeyPath);
267	  } catch (e) {
268	    const details = `repo materialization failed: ${String(e)}`;
269	    emit({ type: "executor_fatal", task_id: taskId, details });
270	    writeResult(resultPath, {
271	      terminal_status: "failed",
272	      blocked_reason: `repo_materialization_failed: ${String(e)}`,
273	    });
274	    process.exit(0);
275	  }
276	
277	  // ── 2. Toolchain pre-flight check ──────────────────────────────────────────
278	  const missingTools = checkRequiredTools(taskRepoPath);
279	  if (missingTools.length > 0) {
280	    const details = `missing tools: ${missingTools.join(", ")}`;
281	    emit({ type: "preflight_failed", task_id: taskId, feature_id: featureId, details });
282	    writeResult(resultPath, {
283	      terminal_status: "blocked",
284	      blocked_reason: "missing_tool",
285	      blocked_suggestion: `Install missing tools in the executor image: ${missingTools.join(", ")}`,
286	    });
287	    process.exit(0);
288	  }
289	
290	  // ── 3. Workspace rules + global skills ─────────────────────────────────────
291	  if (workspaceRoot) copyWorkspaceClaude(workspaceRoot);
292	  if (workspaceRoot && workflowLocalPath) setupGlobalSkills(workspaceRoot, workflowLocalPath);
293	
294	  // ── 4. Read briefing ────────────────────────────────────────────────────────
295	  let briefingContent: string;
296	  try {
297	    briefingContent = readFileSync(briefingPath, "utf-8");
298	  } catch (e) {
299	    emit({ type: "executor_fatal", task_id: taskId, details: `briefing read failed: ${String(e)}` });
300	    writeResult(resultPath, {
301	      terminal_status: "failed",
302	      blocked_reason: `briefing_read_failed: ${String(e)}`,
303	    });
304	    process.exit(0);
305	  }
306	
307	  // Append hard-stop rule for missing tools.
308	  const effectiveBriefing =
309	    briefingContent +
310	    `\n\n## Hard stop rule — missing tools\nIf any shell command exits with code 127 ("command not found"), do NOT attempt to install it or work around it. Immediately write \`{"terminal_status":"blocked","blocked_reason":"missing_tool"}\` to \`${resultPath}\` and stop.`;
311	
312	  // ── 5. Build MCP config ─────────────────────────────────────────────────────
313	  const mcpArgs: string[] = [];
314	  if (mcpRagUrl || figmaToken) {
315	    const mcpConfig: { mcpServers: Record<string, unknown> } = { mcpServers: {} };
316	    if (mcpRagUrl) {
317	      mcpConfig.mcpServers["rag-server"] = { type: "streamable-http", url: `${mcpRagUrl}/mcp` };
318	    }
319	    if (figmaToken) {
320	      mcpConfig.mcpServers["figma"] = {
321	        type: "stdio",
322	        command: "npx",
323	        args: ["-y", "@figma/mcp-server"],
324	        env: { FIGMA_PERSONAL_ACCESS_TOKEN: figmaToken },
325	      };
326	    }
327	    const mcpConfigPath = `/tmp/mcp-config-${taskId}.json`;
328	    writeFileSync(mcpConfigPath, JSON.stringify(mcpConfig));
329	    mcpArgs.push("--mcp-config", mcpConfigPath);
330	  }
331	
332	  if (mcpRagUrl) {
333	    emit({ type: "rag_mcp_registered", url: mcpRagUrl });
334	  } else {
335	    emit({ type: "rag_mcp_unavailable", reason: "MCP_RAG_URL not set" });
336	  }
337	
338	  // ── 6. Spawn claude — wrapped in try/finally for Layer 1 recovery ───────────
339	  const claudeEnv = {
340	    ...buildGitEnv(sshKeyPath),
341	    CLAUDE_AGENT_RUNTIME: "1",
342	    RESULT_PATH: resultPath,
343	    GITHUB_TOKEN: githubToken,
344	  };
345	
346	  emit({ type: "claude_spawn", task_id: taskId, feature_id: featureId, max_turns: maxTurns });
347	
348	  let spawnResult: SpawnResult | undefined;
349	  let tokenUsage: { input: number; output: number; model: string; cost_usd: number; pricingFallback: boolean } | undefined;
350	  let logFlushed = false;
351	
352	  try {
353	    spawnResult = await new Promise<SpawnResult>((resolve) => {
354	      const stdoutChunks: string[] = [];
355	
356	      const child = spawn(
357	        "claude",
358	        [
359	          "-p", effectiveBriefing,
360	          "--max-turns", String(maxTurns),
361	          "--output-format", "stream-json",
362	          "--verbose",
363	          "--dangerously-skip-permissions",
364	          ...(implementationModel ? ["--model", implementationModel] : []),
365	          ...mcpArgs,
366	        ],
367	        { cwd: taskRepoPath, env: claudeEnv },
368	      );
369	
370	      child.stdout.setEncoding("utf-8");
371	      child.stderr.setEncoding("utf-8");
372	
373	      let resultWatchdog: ReturnType<typeof setTimeout> | null = null;
374	      let stdoutLineBuf = "";
375	      child.stdout.on("data", (chunk: string) => {
376	        stdoutChunks.push(chunk);
377	        process.stdout.write(chunk);
378	        if (resultWatchdog === null) {
379	          stdoutLineBuf += chunk;
380	          const lines = stdoutLineBuf.split("\n");
381	          stdoutLineBuf = lines.pop() ?? "";
382	          for (const line of lines) {
383	            if (line.includes('"type":"result"')) {
384	              resultWatchdog = setTimeout(() => {
385	                if (!child.killed) child.kill("SIGTERM");
386	              }, 30_000);
387	              break;
388	            }
389	          }
390	        }
391	      });
392	
393	      child.stderr.on("data", (chunk: string) => {
394	        process.stderr.write(chunk);
395	      });
396	
397	      child.on("error", (err: Error) => {
398	        if (resultWatchdog !== null) clearTimeout(resultWatchdog);
399	        resolve({ stdout: stdoutChunks.join(""), status: null, signal: null, error: err });
400	      });
401	
402	      child.on("exit", () => {
403	        if (resultWatchdog !== null) clearTimeout(resultWatchdog);
404	        setTimeout(() => {
405	          if (!child.stdout.destroyed) child.stdout.destroy();
406	          if (!child.stderr.destroyed) child.stderr.destroy();
407	        }, 0);
408	      });
409	
410	      child.on("close", (code: number | null, signal: string | null) => {
411	        resolve({ stdout: stdoutChunks.join(""), status: code, signal });
412	      });
413	    });
414	
415	    emit({
416	      type: "claude_exit",
417	      task_id: taskId,
418	      feature_id: featureId,
419	      exit_code: spawnResult.status,
420	      signal: spawnResult.signal ?? null,
421	    });
422	
423	    // ── 7. Token audit ────────────────────────────────────────────────────────
424	    tokenUsage = spawnResult.stdout ? extractTokenUsage(spawnResult.stdout) : undefined;
425	
426	    if (tokenUsage === undefined) {
427	      emit({ type: "budget_audit_skipped", task_id: taskId, reason: "usage format not found" });
428	    } else {
429	      if (tokenUsage.pricingFallback) {
430	        emit({ type: "pricing_fallback", task_id: taskId, model: tokenUsage.model, note: "unknown model — Sonnet rates applied" });
431	      }
432	      emit({
433	        type: "budget_audit",
434	        task_id: taskId,
435	        feature_id: featureId,
436	        total_tokens: tokenUsage.input + tokenUsage.output,
437	        max_tokens: budgetTokens,
438	      });
439	    }
440	
441	    // ── 7a. RAG query audit
442	    if (spawnResult.stdout) {
443	      for (const rq of extractRagQueries(spawnResult.stdout)) {
444	        emit({ type: "rag_query", ...rq });
445	      }
446	    }
447	
448	    // ── 8. Check for result.json written by Claude ────────────────────────────
449	    // The pr_url is sourced ONLY from Claude's result.json. The executor does not
450	    // scrape stdout for GitHub URLs, and does not synthesize an in_review result
451	    // when Claude exits cleanly without writing result.json — both paths previously
452	    // produced false-positives where unrelated PR URLs (e.g. the workspace claim PR
453	    // echoed via a Read of T<n>.yaml) were captured as the impl PR.
454	
455	    if (existsSync(resultPath)) {
456	      let raw: unknown;
457	      try {
458	        raw = JSON.parse(readFileSync(resultPath, "utf-8"));
459	      } catch {
460	        raw = null;
461	      }
462	      if (isValidResult(raw)) {
463	        let claudeResult = raw as ExecutorResult;
464	        if (tokenUsage !== undefined && !claudeResult.token_usage) {
465	          claudeResult.token_usage = { input: tokenUsage.input, output: tokenUsage.output, model: tokenUsage.model };
466	        }
467	        if (tokenUsage !== undefined && claudeResult.cost_usd === undefined) {
468	          claudeResult.cost_usd = tokenUsage.cost_usd;
469	        }
470	
471	        // Refuse terminal_status: in_review without a pr_url. Catches the case
472	        // where the agent skipped pr-create after pr-self-review and exited
473	        // anyway, so the orchestrator does not advance the task to in_review
474	        // with no impl PR (or with the workspace claim PR url misclaimed as
475	        // the impl PR — see enforce-pr-url.ts for context).
476	        const enforced = enforceInReviewRequiresPrUrl(claudeResult);
477	        if (enforced.rewritten) {
478	          emit({
479	            type: "in_review_refused_no_pr_url",
480	            task_id: taskId,
481	            feature_id: featureId,
482	          });
483	        }
484	        claudeResult = enforced.result;
485	
486	        if (
487	          budgetTokens !== undefined &&
488	          tokenUsage !== undefined &&
489	          tokenUsage.input + tokenUsage.output > budgetTokens
490	        ) {
491	          writeResult(resultPath, {
492	            terminal_status: "blocked",
493	            blocked_reason: "budget_exceeded",
494	            token_usage: tokenUsage,
495	          });
496	        } else {
497	          writeResult(resultPath, claudeResult);
498	        }
499	
500	        if (logSinkEnabled && workspaceRoot && taskBranch) {
501	          flushLog(workspaceRoot, featureId, taskId, taskBranch, runStartIso, gitAuthorEmail, gitAuthorName, spawnResult.stdout, claudeResult.terminal_status, sshKeyPath);
502	          logFlushed = true;
503	        }
504	
505	        // Return normally — Layer 1 recovery (finally block below) will no-op
506	        // because a valid result.json now exists.
507	        return;
508	      }
509	    }
510	
511	    // ── 9. Claude did not write result.json ──────────────────────────────────
512	    // Budget-exceeded: write blocked immediately (deterministic, no recovery side-effects needed).
513	    if (
514	      budgetTokens !== undefined &&
515	      tokenUsage !== undefined &&
516	      tokenUsage.input + tokenUsage.output > budgetTokens
517	    ) {
518	      writeResult(resultPath, {
519	        terminal_status: "blocked",
520	        blocked_reason: "budget_exceeded",
521	        token_usage: tokenUsage,
522	      });
523	      if (logSinkEnabled && workspaceRoot && taskBranch) {
524	        flushLog(workspaceRoot, featureId, taskId, taskBranch, runStartIso, gitAuthorEmail, gitAuthorName, spawnResult.stdout, "blocked", sshKeyPath);
525	        logFlushed = true;
526	      }
527	      return;
528	    }
529	
530	    // No result.json produced — recovery will write one in the finally block.
531	
532	  } finally {
533	    // ── Layer 1: post-hoc recovery ────────────────────────────────────────────
534	    // Runs regardless of how the spawn ended. No-op when result.json has a
535	    // valid in_review result (Claude finished cleanly). Otherwise: commits
536	    // uncommitted work, pushes, opens a draft PR, writes handover.md, and
537	    // writes a blocked result.json.
538	    await runRecovery({
539	      spawnResult,
540	      taskId,
541	      featureId,
542	      taskRepoBranch,
543	      taskRepoPath,
544	      taskRepoUrl,
545	      githubToken,
546	      sshKeyPath,
547	      gitAuthorEmail,
548	      gitAuthorName,
549	      resultPath,
550	      tokenUsage: tokenUsage ? { input: tokenUsage.input, output: tokenUsage.output } : undefined,
551	    });
552	
553	    // Flush log after recovery (best-effort, uses result.json to determine outcome).
554	    // Skip if already flushed in the success or budget-exceeded paths above.
555	    if (!logFlushed && logSinkEnabled && workspaceRoot && taskBranch) {
556	      let outcome = "unknown";
557	      try {
558	        const raw = JSON.parse(readFileSync(resultPath, "utf-8")) as ExecutorResult;
559	        outcome = raw.terminal_status;
560	      } catch { /* ignore */ }
561	      flushLog(workspaceRoot, featureId, taskId, taskBranch, runStartIso, gitAuthorEmail, gitAuthorName, spawnResult?.stdout ?? "", outcome, sshKeyPath);
562	    }
563	  }
564	}
565	
566	// ── Log flush (best-effort) ───────────────────────────────────────────────────
567	
568	function flushLog(
569	  workspaceRoot: string,
570	  featureId: string,
571	  taskId: string,
572	  taskBranch: string,
573	  runStartIso: string,
574	  gitAuthorEmail: string,
575	  gitAuthorName: string,
576	  stdout: string,
577	  outcome: string,
578	  sshKeyPath: string | undefined,
579	): void {
580	  try {
581	    const safeIso = runStartIso.replace(/[:.]/g, "-");
582	    const logFilename = `${safeIso}.jsonl`;
583	    const relLogPath = join("docs", "features", featureId, "logs", taskId, logFilename);
584	    const logPath = join(workspaceRoot, relLogPath);
585	
586	    const env = {
587	      ...process.env,
588	      GIT_AUTHOR_NAME: gitAuthorName,
589	      GIT_AUTHOR_EMAIL: gitAuthorEmail,
590	      GIT_COMMITTER_NAME: gitAuthorName,
591	      GIT_COMMITTER_EMAIL: gitAuthorEmail,
592	      ...(sshKeyPath ? { GIT_SSH_COMMAND: `ssh -i "${sshKeyPath}" -o StrictHostKeyChecking=accept-new` } : {}),
593	    };
594	    const gitOpts = { env, stdio: "pipe" as const, timeout: 30_000 };
595	
596	    // Step 1: Move to the task branch tip BEFORE writing any files.
597	    // Discard local changes first — a previous failed flush may have left a dirty tree.
598	    execSync(`git -C "${workspaceRoot}" fetch origin "${taskBranch}"`, gitOpts);
599	    execSync(`git -C "${workspaceRoot}" checkout -- .`, gitOpts);
600	    execSync(`git -C "${workspaceRoot}" checkout "${taskBranch}"`, gitOpts);
601	
602	    // Step 2: Write the log file (directory may not exist on this branch yet).
603	    const logsDir = join(workspaceRoot, "docs", "features", featureId, "logs", taskId);
604	    mkdirSync(logsDir, { recursive: true });
605	    appendFileSync(logPath, JSON.stringify({ at: runStartIso, by: gitAuthorEmail, type: "run_started" }) + "\n");
606	    if (stdout) {
607	      const safe = redactSecrets(stdout);
608	      appendFileSync(logPath, safe.endsWith("\n") ? safe : safe + "\n");
609	    }
610	    appendFileSync(logPath, JSON.stringify({ at: new Date().toISOString(), by: gitAuthorEmail, type: "run_ended", details: { outcome } }) + "\n");
611	
612	    // Step 3: Commit, sync with origin, then push.
613	    execSync(`git -C "${workspaceRoot}" add "${relLogPath}"`, gitOpts);
614	    execSync(`git -C "${workspaceRoot}" commit -m "chore: flush task log ${taskId}"`, gitOpts);
615	    execSync(`git -C "${workspaceRoot}" pull --rebase origin "${taskBranch}"`, gitOpts);
616	    execSync(`git -C "${workspaceRoot}" push origin "${taskBranch}"`, gitOpts);
617	  } catch { /* best-effort */ }
618	}
619	
620	main().catch((e) => {
621	  try {
622	    console.log(JSON.stringify({ type: "fatal_error", details: String(e), at: new Date().toISOString() }));
623	  } catch { /* last resort */ }
624	  process.exit(1);
625	});
