1	/**
2	 * ABI contract between the orchestrator and any executor.
3	 *
4	 * The orchestrator serialises ExecutorInput into env vars before spawning
5	 * the executor process. The executor writes an ExecutorResult to the path
6	 * at resultPath. The orchestrator reads and validates that file on exit.
7	 */
8	
9	// ── Handle / completion types (Wave 1 — ports-and-adapters foundation) ───────
10	
11	/** Opaque identifier for a single in-flight executor run. */
12	export type ExecutorHandle = string;
13	
14	/** Discriminates claim work from review-fix work in the reap loop. */
15	export type HandleKind = "impl" | "review-fix";
16	
17	/** Sub-discriminator for review-fix handles. */
18	export type HandleSubkind = "rebase" | "respond";
19	
20	/**
21	 * Metadata registered with the broker at submit time.
22	 * Carried on every completion so any orchestrator can dispatch without
23	 * needing prior knowledge of the submit — opportunistic dispatch.
24	 */
25	export interface HandleMetadata {
26	  kind: HandleKind;
27	  subkind?: HandleSubkind;
28	  task_id: string;
29	  feature_id: string;
30	  tenant_id?: string;
31	  started_at: string; // ISO 8601
32	}
33	
34	/**
35	 * One item returned by CompletionBrokerPort.listCompleted (peek-and-lock).
36	 * locked_until is present when the broker has marked the item locked.
37	 */
38	export interface ExecutorCompletion {
39	  handle: ExecutorHandle;
40	  result: ExecutorResult;
41	  metadata: HandleMetadata;
42	  locked_until?: number; // unix ms timestamp
43	}
44	
45	/**
46	 * Extended input for ExecutorPort.submit.
47	 * Adds the callback URL and per-handle nonce that the runner wrapper uses
48	 * to POST its result back to the completion broker.
49	 */
50	export interface ExecutorPortInput extends ExecutorInput {
51	  /** The URL the runner wrapper will POST { handle, nonce, result } to. */
52	  callbackUrl: string;
53	  /** Single-use token; validated by the broker on POST; invalidated on ack. */
54	  nonce: string;
55	}
56	
57	/** HTTP POST body the runner wrapper sends to the broker on completion. */
58	export interface RunnerCallbackPayload {
59	  handle: ExecutorHandle;
60	  nonce: string;
61	  result: ExecutorResult;
62	}
63	
64	// ── Original ABI types (kept for backward compatibility) ─────────────────────
65	
66	export interface ExecutorInput {
67	  taskId: string;
68	  featureId: string;
69	  workspaceId: string;
70	  /** Git URL of the implementation repo (SSH or HTTPS). */
71	  taskRepoUrl: string;
72	  /** Feature branch the executor must check out and push to. */
73	  taskRepoBranch: string;
74	  /**
75	   * Working-directory path. The **executor** materializes the repo here:
76	   * if the path already exists with `origin` matching `taskRepoUrl`,
77	   * fetch + checkout + pull; otherwise clone fresh from `taskRepoUrl`.
78	   * The orchestrator may pre-populate this path as an optimization in
79	   * shared-filesystem topologies, but it is not required to.
80	   */
81	  taskRepoPath: string;
82	  /** Path to the markdown briefing file written by the orchestrator. */
83	  briefingPath: string;
84	  /** Path the executor must write result.json to. */
85	  resultPath: string;
86	  /** Optional token budget; absent for non-LLM executors. */
87	  budgetTokens?: number;
88	  /** Model ID to use for the LLM; resolved from workspace model_policy. */
89	  implementationModel?: string;
90	  sshPrivateKey: string;
91	  githubToken: string;
92	}
93	
94	export type TerminalStatus = "in_review" | "blocked" | "failed";
95	
96	export interface ExecutorResult {
97	  terminal_status: TerminalStatus;
98	  token_usage?: { input: number; output: number; model?: string };
99	  /** Required when terminal_status === "blocked". */
100	  blocked_reason?: string;
101	  /** Required when terminal_status === "blocked". */
102	  blocked_suggestion?: string;
103	  /**
104	   * URL of the implementation-repo pull request opened by the executor.
105	   * Populated whenever the executor opened a PR — independent of terminal_status.
106	   * A blocked task with a draft PR still reports pr_url so the failed attempt is
107	   * documented. Absent when no commits were pushed (no PR to open).
108	   */
109	  pr_url?: string;
110	  /**
111	   * Path to a handover.md file written by the executor or the post-hoc recovery
112	   * routine (Layer 1). Optional — present only when a handover exists.
113	   * The orchestrator reads this on re-claim and prepends its contents to the next
114	   * agent's briefing under a "## Continuing previous run" heading (Layer 3).
115	   */
116	  cost_usd?: number;
117	  handover_path?: string;
118	}
119	
120	/**
121	 * The orchestrator-side seam every executor must satisfy.
122	 * The default implementation is SubProcessAdapter; tests use FakeAdapter.
123	 */
124	export interface ExecutorAdapter {
125	  run(input: ExecutorInput): Promise<ExecutorResult>;
126	}
127

