import { describe, it, expect } from "vitest";
import { extractTokenUsage } from "./token-usage.js";

describe("extractTokenUsage", () => {
  it("returns undefined for empty stdout", () => {
    expect(extractTokenUsage("")).toBeUndefined();
  });

  it("returns undefined for stdout with no usage lines", () => {
    expect(extractTokenUsage("hello\nworld\n")).toBeUndefined();
  });

  it("sums token counts across multiple assistant turns", () => {
    const stdout = [
      JSON.stringify({ type: "assistant", message: { model: "claude-sonnet-4-6", usage: { input_tokens: 100, output_tokens: 50 } } }),
      JSON.stringify({ type: "assistant", message: { model: "claude-sonnet-4-6", usage: { input_tokens: 200, output_tokens: 80 } } }),
    ].join("\n");
    const r = extractTokenUsage(stdout);
    expect(r?.input).toBe(300);
    expect(r?.output).toBe(130);
  });

  it("captures model from last assistant event", () => {
    const stdout = [
      JSON.stringify({ type: "assistant", message: { model: "claude-sonnet-4-6", usage: { input_tokens: 10, output_tokens: 5 } } }),
      JSON.stringify({ type: "assistant", message: { model: "claude-opus-4-7", usage: { input_tokens: 20, output_tokens: 10 } } }),
    ].join("\n");
    const r = extractTokenUsage(stdout);
    expect(r?.model).toBe("claude-opus-4-7");
  });

  it("computes correct cost_usd for claude-sonnet-4-6", () => {
    const stdout = JSON.stringify({
      type: "assistant",
      message: { model: "claude-sonnet-4-6", usage: { input_tokens: 1_000_000, output_tokens: 1_000_000 } },
    });
    const r = extractTokenUsage(stdout);
    expect(r?.cost_usd).toBeCloseTo(3.0 + 15.0, 5);
    expect(r?.pricingFallback).toBe(false);
  });

  it("computes correct cost_usd for claude-opus-4-7", () => {
    const stdout = JSON.stringify({
      type: "assistant",
      message: { model: "claude-opus-4-7", usage: { input_tokens: 1_000_000, output_tokens: 1_000_000 } },
    });
    const r = extractTokenUsage(stdout);
    expect(r?.cost_usd).toBeCloseTo(15.0 + 75.0, 5);
    expect(r?.pricingFallback).toBe(false);
  });

  it("computes correct cost_usd for claude-haiku-4-5-20251001", () => {
    const stdout = JSON.stringify({
      type: "assistant",
      message: { model: "claude-haiku-4-5-20251001", usage: { input_tokens: 1_000_000, output_tokens: 1_000_000 } },
    });
    const r = extractTokenUsage(stdout);
    expect(r?.cost_usd).toBeCloseTo(0.8 + 4.0, 5);
    expect(r?.pricingFallback).toBe(false);
  });

  it("falls back to Sonnet rates for unknown model and sets pricingFallback", () => {
    const stdout = JSON.stringify({
      type: "assistant",
      message: { model: "claude-unknown-model-99", usage: { input_tokens: 1_000_000, output_tokens: 1_000_000 } },
    });
    const r = extractTokenUsage(stdout);
    expect(r?.model).toBe("claude-unknown-model-99");
    expect(r?.pricingFallback).toBe(true);
    expect(r?.cost_usd).toBeCloseTo(3.0 + 15.0, 5);
  });

  it("falls back to Sonnet model when no model in stream", () => {
    const stdout = JSON.stringify({
      type: "assistant",
      message: { usage: { input_tokens: 100, output_tokens: 50 } },
    });
    const r = extractTokenUsage(stdout);
    expect(r?.model).toBe("claude-sonnet-4-6");
    expect(r?.pricingFallback).toBe(false);
  });

  it("handles legacy flat usage shape", () => {
    const stdout = JSON.stringify({ usage: { input_tokens: 500, output_tokens: 200 } });
    const r = extractTokenUsage(stdout);
    expect(r?.input).toBe(500);
    expect(r?.output).toBe(200);
    expect(r?.model).toBe("claude-sonnet-4-6");
  });
});

